function retrieveAndRankTextWithStoredEmbeddings(query, sheetId, sheetName) {
  const sheet = SpreadsheetApp.openById(sheetId).getSheetByName(sheetName);
  const dataRange = sheet.getDataRange();
  const data = dataRange.getValues();
  const queryEmbedding = generateEmbeddings(query);

  let rankedSegments = [];

  data.forEach(row => {
    const paragraph = row[0];
    const storedEmbedding = JSON.parse(row[1]);
    const similarity = cosineSimilarity(queryEmbedding, storedEmbedding);

    rankedSegments.push({ text: paragraph, score: similarity });
  });

  // Sort by similarity score in descending order
  rankedSegments.sort((a, b) => b.score - a.score);

  // Select the top N segments
  const topSegments = rankedSegments.slice(0, 5).map(segment => segment.text);

  return topSegments.join('\n\n');
}

function generateEmbeddings(text) {
  const apiKey = 'sk-Suv5GmCJSGDVP-tR8BynIKeHV07VLwEmn_3TEFo-krT3BlbkFJS0dnHX8XMjkrG9hkh-BvtUaOtz_K3vLj0X2AA2ZJwA'; // Replace with your OpenAI API key !!!
  const url = 'https://api.openai.com/v1/embeddings';

  const data = {
    model: "text-embedding-ada-002", // Use the appropriate model for embeddings
    input: text
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: {
      'Authorization': 'Bearer ' + apiKey
    },
    payload: JSON.stringify(data)
  };

  try {
    const response = UrlFetchApp.fetch(url, options);
    const json = JSON.parse(response.getContentText());
    return json.data[0].embedding;
  } catch (e) {
    Logger.log('Error: ' + e.toString());
    return null;
  }
}

function cosineSimilarity(vecA, vecB) {
  const dotProduct = vecA.reduce((sum, a, idx) => sum + a * vecB[idx], 0);
  const magnitudeA = Math.sqrt(vecA.reduce((sum, a) => sum + a * a, 0));
  const magnitudeB = Math.sqrt(vecB.reduce((sum, b) => sum + b * b, 0));

  return dotProduct / (magnitudeA * magnitudeB);
}

function getRelevantText(query) {
  const sheetId = "1bOMMr1rB873lSfn52mDISgP_3zaADTOJxjx3ShAlCMU";  // Replace with the ID of the sheet storing embeddings !!!
  const sheetName = "Sheet1";   // Replace with the name of the sheet in the Google Sheet

  const relevantText = retrieveAndRankTextWithStoredEmbeddings(query, sheetId, sheetName);
  return relevantText;
}

