  const apiKey = 'sk-Suv5GmCJSGDVP-tR8BynIKeHV07VLwEmn_3TEFo-krT3BlbkFJS0dnHX8XMjkrG9hkh-BvtUaOtz_K3vLj0X2AA2ZJwA'; // Replace with your OpenAI API key !!!
  const url = 'https://api.openai.com/v1/chat/completions';

  const data = {
    model: "gpt-4",
    messages: [
      { role: "system", content: "You are a helpful assistant." },
      { role: "user", content: query }
    ],
    max_tokens: 150
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: {
      'Authorization': 'Bearer ' + apiKey
    },
    payload: JSON.stringify(data)
  };

  try {
    const response = UrlFetchApp.fetch(url, options);
    const json = JSON.parse(response.getContentText());
    return json.choices[0].message.content;
  } catch (e) {
    Logger.log('Error: ' + e.toString());
    return 'Error: ' + e.toString();
  }
}

function getChatGPTCustom(query, context) {
  const apiKey = 'sk-Suv5GmCJSGDVP-tR8BynIKeHV07VLwEmn_3TEFo-krT3BlbkFJS0dnHX8XMjkrG9hkh-BvtUaOtz_K3vLj0X2AA2ZJwA'; // Replace with your OpenAI API key !!!
  const url = 'https://api.openai.com/v1/chat/completions';

  const prompt = `Context: ${context}\n\nUser Query: ${query}`;

  const data = {
    model: "gpt-4",
    messages: [
      { role: "system", content: "You are a helpful assistant." },
      { role: "user", content: prompt }
    ],
    max_tokens: 300 //This can be increased if you want longer answers, but they are not forced to be longer !!!
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: {
      'Authorization': 'Bearer ' + apiKey
    },
    payload: JSON.stringify(data)
  };

  try {
    const response = UrlFetchApp.fetch(url, options);
    const json = JSON.parse(response.getContentText());
    return json.choices[0].message.content;
  } catch (e) {
    Logger.log('Error: ' + e.toString());
    return 'Error: ' + e.toString();
  }
}

function getAnswers(query) {
  const relevantText = getRelevantText(query);
  const standardAnswer = getChatGPTStandard(query);
  const customAnswer = getChatGPTCustom(query, relevantText);

  return {
    standard: standardAnswer,
    custom: customAnswer,
    relevantText: relevantText
  };
}
